I've added castle ticket times right below Saturday, with 11:30 picked to fit between the flea market and lunch.

```svelte file=lib/CastleTickets.svelte
<script>
  import { Section, Action, ask } from 'design';
  import Ticket from 'phosphor-svelte/lib/Ticket';
  import PaperPlaneTilt from 'phosphor-svelte/lib/PaperPlaneTilt';

  const slots = [
    { time: '11:00', left: 'Few left' },
    { time: '11:30', left: 'Open' },
    { time: '12:00', left: 'Open' },
    { time: '12:30', left: 'Open' }
  ];

  let chosen = $state('11:30');
  let bought = $state(false);
  let sent = $state(false);
</script>

<Section title="Castle tickets" kicker="Castelo de São Jorge · Sat Nov 14">
  <div class="slots" role="radiogroup" aria-label="Entry time">
    {#each slots as slot}
      <button
        class="slot"
        class:on={chosen === slot.time}
        role="radio"
        aria-checked={chosen === slot.time}
        disabled={bought}
        onclick={() => (chosen = slot.time)}
      >
        <span class="time">{slot.time}</span>
        <span class="left">{slot.left}</span>
      </button>
    {/each}
  </div>
  <p class="m-price">€15.00</p>
  <p class="m-meta">1 adult · entry {chosen}
Lunch at Prato Saveiro is at 13:30, about 10 min downhill on foot.</p>
  {#snippet actions()}
    <Action
      label={bought ? 'Ticket bought' : 'Buy ticket'}
      sublabel={bought ? `Sat ${chosen} · show the code at the gate` : `Sat ${chosen} · €15`}
      icon={Ticket}
      primary
      disabled={bought}
      onclick={() => (bought = true)}
    />
    <Action
      label={sent ? 'Sent to phone' : 'Send to phone'}
      icon={PaperPlaneTilt}
      disabled={!bought || sent}
      onclick={() => (sent = true)}
    />
  {/snippet}
</Section>

<style>
  .slots {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 8px;
  }
  .slot {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    padding: 10px 6px;
    border: none;
    border-radius: var(--m-radius-sm);
    background: var(--m-tint);
    box-shadow: var(--m-shadow-line);
    color: var(--m-ink);
    cursor: pointer;
  }
  .slot.on {
    background: var(--m-accent);
    color: var(--m-accent-ink);
  }
  .slot:disabled {
    cursor: default;
  }
  .time {
    font-size: var(--m-type-tab);
  }
  .left {
    font-size: var(--m-type-caption);
    color: var(--m-ink-3);
  }
  .slot.on .left {
    color: var(--m-accent-ink);
  }
</style>
```

